border:3px solid #fff9e8;border-radius:18px;color:#49354b;padding:clamp(13px,4vw,20px);box-shadow:0 6px 0 #b6685a,0 10px 20px #21142c66}.card h2{font-family:'Lilita One';font-size:27px;color:#633f56;margin:0 0 8px}.card p{margin:5px 0;line-height:1.35}.button-row{display:flex;flex-direction:column;gap:9px;width:100%;max-width:330px;margin-top:12px}.btn{position:relative;border:0;border-radius:13px;padding:12px 16px;font:700 18px 'Fredoka',sans-serif;color:#fffdf1;cursor:pointer;background:#ed7653;box-shadow:0 4px 0 #ae4c4a,0 6px 12px #29182d55;text-shadow:0 1px #9d4646;transition:transform .09s,filter .09s}.btn:hover{filter:brightness(1.09);transform:translateY(-1px)}.btn:active{transform:translateY(3px);box-shadow:0 1px 0 #ae4c4a}.btn.secondary{background:#60b9a2;box-shadow:0 4px 0 #378c83,0 6px 12px #29182d55}.btn.gold{background:#f1ba45;box-shadow:0 4px 0 #c98734,0 6px 12px #29182d55}.btn.small{font-size:14px;padding:8px 13px}.btn:disabled{opacity:.5;filter:grayscale(.4);cursor:default}.screen-footer{font-size:11px;color:#fff8dfaa;margin-top:14px}.topline{font-size:12px;color:#95728b;letter-spacing:1px}.level-list{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:12px 0;max-height:210px;overflow:auto}.level-tile{border:2px solid #ead3ac;border-radius:10px;background:#fff9e8;color:#65465c;font:700 16px 'Fredoka';padding:9px 3px;cursor:pointer}.level-tile.selected{background:#ffe27a;border-color:#e59b51;transform:scale(1.05)}.level-tile:disabled{opacity:.43;cursor:default}.upgrade{display:grid;grid-template-columns:88px 1fr 30px 32px;align-items:center;gap:5px;margin:12px 0;text-align:left}.upgrade-name{font-weight:700}.upgrade-bar{height:11px;border-radius:8px;background:#e8d4b8;overflow:hidden}.upgrade-fill{height:100%;background:linear-gradient(90deg,#ffb748,#ee7752);border-radius:8px}.upgrade-num{font-size:12px;color:#95728b;text-align:center}.upgrade .btn{width:30px;height:30px;padding:0;line-height:30px;font-size:19px;border-radius:9px}.chip-count{color:#d58b23;font-family:'Lilita One';font-size:20px}.race-hud{position:absolute;inset:0;pointer-events:none}.hud-top{position:absolute;top:3%;left:5%;right:5%;display:flex;justify-content:space-between;align-items:flex-start;text-shadow:0 2px 3px #33283b}.hud-distance{font:26px 'Lilita One';color:#fff7d7}.hud-distance span{font-size:12px;letter-spacing:1px}.hud-level{font-size:12px;color:#fff4d9}.hud-objectives{position:absolute;top:10%;left:5%;display:flex;gap:5px}.objective{font-size:11px;border-radius:9px;padding:4px 7px;background:#30243c99;color:#fff1cf}.objective.done{background:#3e9f75e8}.hud-position{position:absolute;top:3%;right:5%;font-weight:700;color:#ffe36f;font-size:13px}.hold-control{position:absolute;bottom:4%;left:50%;transform:translateX(-50%);pointer-events:auto;display:flex;align-items:center;gap:9px;white-space:nowrap;padding:11px 22px;border:3px solid #fff4d5;border-radius:28px;background:#ef7851;color:white;font:700 15px 'Fredoka';box-shadow:0 4px 0 #a84648,0 8px 20px #2b1d3b88;cursor:pointer;touch-action:none}.hold-control.active{background:#62bca4;transform:translate(-50%,3px);box-shadow:0 1px 0 #358d7f}.hold-dot{width:12px;height:12px;border-radius:50%;background:#ffe475}.chip-tracker{position:absolute;bottom:11%;left:50%;transform:translateX(-50%);display:flex;gap:5px}.chip-dot{width:16px;height:16px;border:2px solid #fff0be;border-radius:50%;background:#63485caa}.chip-dot.done{background:#ffcf53;box-shadow:0 0 8px #fff48f}.race-controls{position:absolute;top:3%;right:4%;display:flex;gap:6px;pointer-events:auto}.race-controls button{border:2px solid #fff3d5;border-radius:50%;width:32px;height:32px;background:#45344daa;color:white;font:700 14px 'Fredoka';cursor:pointer}.hidden{display:none!important}.upgrade-screen{max-height:88%;overflow:auto}.race-note{font-size:12px;color:#997584}.controls-copy{font-size:13px}.result-badges{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:12px 0}.result-badge{background:#fff8e6;border-radi